INSERT INTO `relationships` VALUES (29, 87, '2024-05-15 14:15:00', 'No', NULL, NULL, 'La herida paterna ,(Líder que Brilla', 'Si', 'Si', NULL, NULL, NULL, 'En este momento la hermana por problemas de salud , nos reunimos cada 15 días .Y está siendo ayudada por Walter Denes en su cédula.', '3dbabcb0-2757-11ef-a443-87908085dbb1', '2024-06-10 18:28:32', '2024-06-10 18:28:32');
INSERT INTO `relationships` VALUES (29, 87, '2024-05-29 02:13:00', 'Si', 'Por el fallecimiento de su hermana .', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Oremos por Norma. Y su familia', 'a2e97350-2757-11ef-a1b9-e11d31e4cd20', '2024-06-10 18:31:22', '2024-06-10 18:31:22');
INSERT INTO `relationships` VALUES (29, 87, '2024-06-05 14:20:00', 'Si', 'Fue suspendida por corte de luz y por la lluvia no pudo salir de su casa vive en el piso 11', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Oremos se solucione el problema de Luz ya que lo arreglan y saltan los tapones y todo el edificio queda sin luz', '1c433860-2758-11ef-b6a6-a1c6ad05a600', '2024-06-10 18:34:45', '2024-06-10 18:34:45');
