INSERT INTO `relationships` VALUES (29, 81, '2024-05-21 10:30:00', 'No', NULL, NULL, 'Aprender a imitar la Fede otro', 'Si', 'Si', NULL, NULL, NULL, 'Somos bendecidas de poder estudiar juntas en este tiempo, ya que a pesar de tantos años siempre Dios nos enseña algo, Seguimos aprendiendo', 'b3f87550-275d-11ef-ae16-690cdef6addd', '2024-06-10 19:14:47', '2024-06-10 19:14:47');
INSERT INTO `relationships` VALUES (29, 81, '2024-05-28 10:30:00', 'No', NULL, NULL, 'En defensa del Líder y la misión', 'Si', 'Si', NULL, NULL, NULL, 'Que siempre estemos en oración cubriendo nuestros Pastores y aprender de Ellos', '1c419c60-275e-11ef-bbb3-dfdfef4708cc', '2024-06-10 19:17:42', '2024-06-10 19:17:42');
