INSERT INTO `relationships` VALUES (10, 105, '2024-05-29 08:40:00', 'No', NULL, NULL, 'CÓMO LEER LA BIBLIA DE FORMA EDIFICANTE lección 3', 'Si', 'Si', NULL, NULL, NULL, 'Fue de mucha bendición para ambas recordar lo hermoso que es meditar siempre en su palabra y ponerla en práctica en nuestras vidas día a día', '71831080-27a2-11ef-b950-85a29f98cfaf', '2024-06-11 03:26:51', '2024-06-11 03:26:51');
