INSERT INTO `reports_celula` VALUES (1384, 25, '2026-08-29 18:45:00', 'Andrés Arnaldo Alcaraz', 'Lo visible y invisible de Dios', 'No', NULL, 'Andrés Alcaraz', 'Presencial', 6, 1, NULL, 'Sentir a Dios en cada momento aunque no lo pueda ver. \r\nDios es un Dios que me ve..aunque los hombres no valora. El si me ama..y estoy DISPUESTO.', '2026-08-29 19:56:48', '2026-08-29 19:56:48');
