INSERT INTO `reports_celula` VALUES (1387, 5, '2026-08-29 19:30:00', 'Gastón Mantelli', 'Lo visible y lo invisible de Dios', 'No', NULL, 'Gaston Mantelli', 'Presencial', 4, 1, 'Si', 'Gratitudes en sus situaciones,  y vimos cómo todo comienza con una actitud visible! Nos pusimos desafíos a ser de bendición!', '2026-09-03 10:39:59', '2026-09-03 10:39:59');
